import{_ as l,l as o,o as e,c as s,v as r,p as n,x as t,d as p,i as L,S as d}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"MLIR 多层 IR","description":"","frontmatter":{"title":"MLIR 多层 IR","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/mlir.md","filePath":"cs/mlir.md","lastUpdated":1789023840000}'),c={name:"cs/mlir.md"};function m(h,a,I,_,R,M){const i=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="mlir-多层-ir" tabindex="-1">MLIR 多层 IR <a class="header-anchor" href="#mlir-多层-ir" aria-label="Permalink to &quot;MLIR 多层 IR&quot;">​</a></h1><div class="epigraph"><p>同一框架里并存多种方言：张量、循环、LLVM。下降是方言到方言的合法变换，而不是只在一种三地址 IR 上打遍。</p><footer>—— 据 Lattner et al., MLIR: Scaling Compiler Infrastructure for Domain Specific Computation；对照龙书单层 IR 与[目标描述](/cs/target-description) 整理</footer></div><p>上一课<a href="/cs/wasm-target">Wasm</a> 是一个后端方言的归宿。缺口是<strong>多层</strong>：MLIR 让编译器基础设施服务 DSL 与硬件，而不把一切立刻降到 LLVM IR。本课钉方言与 lowering，DSL 下一课。不把神经网络训练当本栏正文——可点名张量方言存在，细节归大模型栏。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>龙书一条管道：源 → 三地址 → 机器。DSL 与加速器要在高层次做变换（融合、布局）。过早降到 LLVM 丢失结构。MLIR：op+类型在方言里，pass 管 lowering。缺口是<strong>这一架构</strong>，不是 Wasm 验证。</p><p>与多面体：affine 方言承接 SCoP。</p><h3 id="mlir-不是「又一个-llvm」" tabindex="-1">MLIR 不是「又一个 LLVM」 <a class="header-anchor" href="#mlir-不是「又一个-llvm」" aria-label="Permalink to &quot;MLIR 不是「又一个 LLVM」&quot;">​</a></h3><p>LLVM IR 是其方言之一。MLIR 是建 IR 的系统。不要把两者当同一文件格式。</p><p><span class="marginnote">Lattner 等 MLIR 论文与 LLVM 项目文档。对照 Appel 单 IR。本课不编造 arXiv 号。基础设施视角，不写具体加速器 ISA。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>定义方言（操作语义、验证器）。写 pass：canonicalization、lowering 到下一方言。最终 <code>llvm</code> 方言 → LLVM 模块 → 原有后端。</p>',11)),(e(),n(d,null,{default:t(()=>[L(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20DSL%5B%22DSL%20%2F%20%E5%BC%A0%E9%87%8F%E6%96%B9%E8%A8%80%22%5D%20--%3E%20AFF%5B%22%E4%BB%BF%E5%B0%84%20%2F%20%E5%BE%AA%E7%8E%AF%22%5D%0A%20%20AFF%20--%3E%20LIR%5B%22LLVM%20%E6%96%B9%E8%A8%80%22%5D%0A%20%20LIR%20--%3E%20BE%5B%22%E6%97%A2%E6%9C%89%E5%90%8E%E7%AB%AF%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>与<a href="/cs/tree-pattern-isel">树匹配</a>：在低层仍做选择；高层做图变换。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>类型系统可依方言扩展（与 HM 不同，是编译器 IR 类型）。调试：位置信息跨 lowering 传递，难。不要一层 pass 偷偷改变内存模型而不声明。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写具体 DSL 嵌入语法。后课默认：多层方言下降是现代基础设施。下一课 DSL 与嵌入。</p><p>也不把 MLIR 当 XML。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MLIR：多方言、逐级 lowering，保住高层次结构。</li><li>LLVM 是终点方言之一，不是唯一 IR。</li><li>服务 DSL 与硬件，不替代源语言类型系统课。</li><li>出处：Lattner et al. MLIR；LLVM 文档；对照龙书管道。</li></ul>',8))])}const E=l(c,[["render",m]]);export{u as __pageData,E as default};
